static const profile_guide_block_t profile_guide_blocks_1[] = {
  {PG_TEXT,"Place one complete profile block near the beginning of the main assembly source file. The opening marker also starts the [profile] section:"},
  {PG_CODE,";[profile]\n;name = My machine\n;cpu = 6502\n;[io]\n;simio_tx_enable = 1\n;simio_tx_addr = 9030\n;simio_rx_enable = 1\n;simio_rx_addr = 9031\n;[/profile]"},
  {PG_TEXT,"Use Assembly → Assemble & Emulate to apply it. The editor extracts the commented settings and opens the simulator with that configuration. These comments do not emit machine code. A CLI assembly alone does not launch this GUI workflow. The examples in individual device sections below are fragments to place inside the same block; the combined example supplies the complete block."},
  {PG_HEADING,"Syntax rules"},
  {PG_TEXT,"• Begin with exactly ;[profile] and end with ;[/profile].\n• Prefix every section header and setting with ;.\n• Use lower-case section names and keys as shown.\n• Write one key = value per line. Do not put explanatory comments after values.\n• Use 0 for disabled and 1 for enabled.\n• Write addresses and memory sizes in hexadecimal: 9000, C000, 4000. Do not use the assembly $ prefix in profile values.\n• Write timing values, SPI frequency, TCP ports, bit numbers, bank numbers and display dimensions in decimal.\n• Write names and paths without quotation marks. Spaces within a path are allowed.\n• Avoid repeating a key. Where accepted repeatedly, later values take precedence.\n• Put an LCD’s bus_width before its data-pin entries."},
  {PG_TEXT,"For explanation within the block, a hash-comment line works:"},
  {PG_CODE,";# LCD on VIA1; SD card on VIA2"},
  {PG_TEXT,"Unrecognised keys are generally ignored rather than reported as assembly errors. A successful assembly therefore does not prove that every profile setting applied."},
  {PG_HEADING,"Inheritance and saved settings"},
  {PG_TEXT,"The editor starts with the last-selected/default saved machine profile and then applies the settings in the source block. If no saved profile is available, it uses built-in profile defaults. Omitted fields retain those inherited values. Explicitly disable unused devices when distributing a self-contained example."},
  {PG_TEXT,"ACIA model, fault and connection fields fall back to saved sim.cfg preferences if neither the source nor the base machine profile specifies them. SD settings come from the base .simprofile or its built-in defaults."},
  {PG_TEXT,"Loading a source profile does not rewrite the saved profile or save its ACIA model/connection overrides as your personal defaults. Deliberately changing ACIA controls or clicking Connect retains the GUI’s normal preference-saving behavior."},
  {PG_TEXT,"A simulator Reset keeps the active session configuration. A fresh Assemble & Emulate reapplies the source settings, so edit the source block if you want a lasting change to that example."},
};
static const profile_guide_block_t profile_guide_blocks_2[] = {
  {PG_TEXT,"These fields belong directly after the opening marker:"},
  {PG_CODE,";[profile]\n;name = LCD and SD development board\n;description = Two VIAs, LCD, ACIA and SD card\n;cpu = 6502"},
  {PG_TABLE,"Key\tMeaning\nname\tShort machine/profile name.\ndescription\tDescription of its purpose.\ncpu\tParsed values: 6502, 6502u, 65c02, 65816.\nglobal\tSaved-profile scope metadata; normally omit in source examples."},
  {PG_TEXT,"The profile’s CPU field is separate from the assembler directive:"},
  {PG_CODE,"    .cpu 6502"},
  {PG_TEXT,"Keep the assembly directive, profile and simulator CPU selection consistent. In the current GTK launch path, the configured simulator CPU takes precedence when the window is created; the profile field alone is not sufficient to switch CPU execution mode. 65816 simulation is incomplete."},
};
static const profile_guide_block_t profile_guide_blocks_3[] = {
  {PG_TEXT,"Up to four ranges are available: [rom0], [rom1], [rom2], [rom3]. A typical example maps its program and vectors into the top 16 KiB:"},
  {PG_CODE,";[rom0]\n;enabled = 1\n;bank = -1\n;from = C000\n;to = FFFF\n;rw_bit = -1\n;lock_bit = -1"},
  {PG_TABLE,"Key\tMeaning\nenabled\tEnable this ROM range.\nbank\t-1 for all banks; use this for ordinary flat-memory examples.\nfrom, to\tInclusive hexadecimal address range.\nrw_bit\tControl-register bit 0–7, or -1 for no control connection.\nlock_bit\tControl-register bit 0–7, or -1 for no lock connection."},
  {PG_TEXT,"This setting does not assemble or relocate the program. Your code still needs a matching origin and vectors, for example .org $C000 and vectors at $FFFA. The editor loads the assembled image separately."},
  {PG_TEXT,"The current ROM model keeps a ROM snapshot for reads. In ROM mode, writes go to underlying shadow RAM while reads continue to return ROM contents. In RAM-overlay mode, reads return that underlying RAM and writes are discarded. This is the simulator’s implemented overlay behavior; it is not ordinary writable RAM mode."},
  {PG_TEXT,"Do not place a ROM range across device registers, zero page or the stack in a basic example. Disable inherited ranges you do not intend to use:"},
  {PG_CODE,";[rom1]\n;enabled = 0\n;[rom2]\n;enabled = 0\n;[rom3]\n;enabled = 0"},
};
static const profile_guide_block_t profile_guide_blocks_4[] = {
  {PG_TEXT,"This optional register controls the rw_bit and lock_bit connections above. For normal examples, leave it disabled:"},
  {PG_CODE,";[rom_ctrl]\n;enabled = 0\n;bank = -1\n;addr = 7FFF"},
  {PG_TEXT,"For an overlay experiment, enable it and assign separate control bits:"},
  {PG_CODE,";[rom0]\n;enabled = 1\n;bank = -1\n;from = C000\n;to = FFFF\n;rw_bit = 0\n;lock_bit = 1\n;[rom_ctrl]\n;enabled = 1\n;bank = -1\n;addr = 7FFF"},
  {PG_TEXT,"A write to $7FFF uses bit 0 to select that range’s read source: 0 = ROM, 1 = shadow RAM. Setting bit 1 locks the range’s control state until reset. Use bits 0–7 only, avoid accidental sharing between ranges, and keep this register outside the ROM/device regions it must coexist with."},
};
static const profile_guide_block_t profile_guide_blocks_5[] = {
  {PG_TEXT,"VIA1 occupies 16 registers starting at its base address:"},
  {PG_CODE,";[io]\n;via1_enable = 1\n;via1_bank = -1\n;via1_addr = 9000"},
  {PG_TEXT,"This maps VIA1 to $9000–$900F. Useful register offsets are:"},
  {PG_TABLE,"Register\tOffset\tWith base $9000\nPort B\t+0\t$9000\nPort A, handshake register\t+1\t$9001\nData-direction register B\t+2\t$9002\nData-direction register A\t+3\t$9003\nTimer 1 counter low/high\t+4, +5\t$9004, $9005\nAuxiliary control register\t+B\t$900B\nPeripheral control register\t+C\t$900C\nInterrupt flag register\t+D\t$900D\nInterrupt enable register\t+E\t$900E"},
  {PG_TEXT,"The profile does not configure data directions, timers, edge detection or interrupt enables. Your code writes those registers. For example, an 8-bit LCD using all of port A and B0–B2 normally needs DDRA = $FF and those three DDRB bits set as outputs."},
  {PG_TEXT,"A pin string such as 1A3 means VIA1, port A, bit 3. Pin strings identify the VIA instance, independently of its register address."},
};
